mapper.select:
select afm.id, afm.name, afm.meta_key, afm.group_id, afm.search, afm.display, afm.type, afm.param, afm.remark, afg.name as afg_name, afg.id as afg_id from asset_field_meta afm left join asset_field_group afg on afm.group_id = afg.id where 1=1
and afm.name like CONCAT('%', #{params.name}, '%')
and afm.key like CONCAT('%', #{params.key}, '%')
and afm.group_id = #{params.groupId}
and afm.search = #{params.search}
and afm.display = #{params.display}
